-- Move all financial records into one workspace, preserving IDs and relationships.
CREATE TABLE IF NOT EXISTS wallets_shared (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80), opening INTEGER NOT NULL CHECK(typeof(opening)='integer' AND abs(opening)<=999999999999), currency TEXT NOT NULL DEFAULT 'SGD' CHECK(currency='SGD'), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)));
INSERT INTO wallets_shared (id,name,opening,currency,archived) SELECT id,name,opening,currency,archived FROM wallets;
CREATE TABLE IF NOT EXISTS entries_shared (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer')), date TEXT NOT NULL CHECK(date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 200), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), wallet_id TEXT NOT NULL, destination_id TEXT, category TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', fingerprint TEXT, FOREIGN KEY(wallet_id) REFERENCES wallets_shared(id), FOREIGN KEY(destination_id) REFERENCES wallets_shared(id), CHECK((kind='transfer' AND destination_id IS NOT NULL AND destination_id<>wallet_id AND category='Transfer') OR (kind<>'transfer' AND destination_id IS NULL)), UNIQUE(id,fingerprint));
INSERT INTO entries_shared (id,kind,date,description,amount,wallet_id,destination_id,category,notes,fingerprint) SELECT id,kind,date,description,amount,wallet_id,destination_id,category,notes,fingerprint FROM entries;
CREATE TABLE IF NOT EXISTS budgets_shared (id TEXT PRIMARY KEY, month TEXT NOT NULL, category TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), UNIQUE(month,category));
INSERT INTO budgets_shared (id,month,category,amount) SELECT MIN(id),month,category,SUM(amount) FROM budgets GROUP BY month,category;
CREATE TABLE IF NOT EXISTS subscriptions_shared (id TEXT PRIMARY KEY, name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), wallet_id TEXT NOT NULL, recurrence TEXT NOT NULL CHECK(recurrence IN ('weekly','monthly','yearly')), next_due TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','paused','cancelled')), FOREIGN KEY(wallet_id) REFERENCES wallets_shared(id));
INSERT INTO subscriptions_shared (id,name,amount,wallet_id,recurrence,next_due,status) SELECT id,name,amount,wallet_id,recurrence,next_due,status FROM subscriptions;
CREATE TABLE IF NOT EXISTS goals_shared (id TEXT PRIMARY KEY, name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), target_date TEXT NOT NULL);
INSERT INTO goals_shared (id,name,amount,target_date) SELECT id,name,amount,target_date FROM goals;
CREATE TABLE IF NOT EXISTS contributions_shared (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES goals_shared(id) ON DELETE CASCADE, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), date TEXT NOT NULL);
INSERT INTO contributions_shared (id,goal_id,amount,date) SELECT id,goal_id,amount,date FROM contributions;
CREATE TABLE IF NOT EXISTS receipts_shared (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL UNIQUE REFERENCES entries_shared(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL);
INSERT INTO receipts_shared (id,entry_id,filename,mime,size) SELECT id,entry_id,filename,mime,size FROM receipts;
DROP TABLE receipts;
DROP TABLE contributions;
DROP TABLE goals;
DROP TABLE subscriptions;
DROP TABLE budgets;
DROP TABLE entries;
DROP TABLE wallets;
ALTER TABLE wallets_shared RENAME TO wallets;
ALTER TABLE entries_shared RENAME TO entries;
ALTER TABLE budgets_shared RENAME TO budgets;
ALTER TABLE subscriptions_shared RENAME TO subscriptions;
ALTER TABLE goals_shared RENAME TO goals;
ALTER TABLE contributions_shared RENAME TO contributions;
ALTER TABLE receipts_shared RENAME TO receipts;
DROP TABLE session;
DROP TABLE account;
DROP TABLE verification;
DROP TABLE login_attempts;
DROP TABLE user;
CREATE INDEX entries_month ON entries(date,kind);
CREATE INDEX entries_wallet ON entries(wallet_id);
CREATE INDEX entries_destination ON entries(destination_id);
CREATE INDEX contribution_goal ON contributions(goal_id,date);
